    if($a==='save'){$d=[$_POST['name'],$_POST['slug'],(float)$_POST['price_monthly'],(float)$_POST['price_yearly'],(int)$_POST['max_projects'],(int)$_POST['max_keywords'],(int)$_POST['max_audits'],(int)$_POST['max_orders'],(int)($_POST['ai_tools']??0),(int)($_POST['seo_tools']??0),(int)($_POST['api_access']??0),(int)($_POST['white_label']??0),$_POST['features']??'',(int)($_POST['is_popular']??0),(int)($_POST['status']??1),(int)($_POST['sort_order']??0)];
    if($id)$pdo->prepare("UPDATE `{$p}plans` SET name=?,slug=?,price_monthly=?,price_yearly=?,max_projects=?,max_keywords=?,max_audits=?,max_orders=?,ai_tools=?,seo_tools=?,api_access=?,white_label=?,features=?,is_popular=?,status=?,sort_order=? WHERE id=?")->execute(array_merge($d,[$id]));
    else $pdo->prepare("INSERT INTO `{$p}plans`(name,slug,price_monthly,price_yearly,max_projects,max_keywords,max_audits,max_orders,ai_tools,seo_tools,api_access,white_label,features,is_popular,status,sort_order)VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)")->execute($d);
    redirect('/admin/plans');}
    if($a==='delete'){$pdo->prepare("DELETE FROM `{$p}plans` WHERE id=?")->execute([$id]);redirect('/admin/plans');}
}
try{$plans=$pdo->query("SELECT pl.*,(SELECT COUNT(*) FROM `{$p}users` WHERE plan=pl.slug) AS user_count FROM `{$p}plans` ORDER BY sort_order")->fetchAll();}catch(Exception $e){$plans=[];}
